def kern(d):
    return {1:1.0,2:0.5,3:0.25,4:0.1}.get(d,0.0)
def mdist(p,q):
    return abs(p//9-q//9)+abs(p%9-q%9)

class Layer:
    def __init__(s, nin):
        s.nin=nin; s.cols=[]; s.bias=[]; s.names={}
    def add(s,name,wdict,bias):
        col=np.zeros(s.nin,np.float32)
        for i,w in wdict.items(): col[i]+=w
        s.names[name]=len(s.cols); s.cols.append(col); s.bias.append(bias)
        return s.names[name]
    def mats(s,nout=512):
        W=np.zeros((s.nin,nout),np.float32); b=np.zeros(nout,np.float32)
        assert len(s.cols)<=nout, len(s.cols)
        for j,c in enumerate(s.cols): W[:,j]=c; b[j]=s.bias[j]
        return W,b

def lin_add(d,idx,w):
    d[idx]=d.get(idx,0)+w

