            if k: lin_add(d,pv[('own',q)],k); lin_add(d,pv[('opp',q)],-k)
        Dlin[p]=d
        L.add(('Dp',p),d,0)
    for p in range(81):
        r,c_=divmod(p,9); dd=min(r,c_,8-r,8-c_)
        d={i:P['inf']*w for i,w in Dlin[p].items()}
        for q in NB[p]:
            lin_add(d,pv[('own',q)],P['ownadj']); lin_add(d,pv[('opp',q)],P['oppadj'])
        L.add(('acc',p),d,OFF+P['prior'][dd])
    L.add(('acc',81),{},OFF)
    layers.append(L)
    # L3, L4: propagate Good; L3 adds EyeS, L4 adds U
    def prop_layer(prev,extra):
        L=Layer(512); pv=prev.names
        for p in range(81): L.add(('own',p),{pv[('own',p)]:1},0)
        for p in range(81): L.add(('opp',p),{pv[('opp',p)]:1},0)
        for c in col:
            for s in range(81):
                d={pv[('G',c,s)]:1}
                for n in NB[s]: lin_add(d,pv[('G',c,n)],1)
                lin_add(d,pv[(c,s)],5); 
                L.add(('G',c,s),d,-5)   # gate: colour(s)
        extra(L,pv)
        return L
    def ex3(L,pv):
        for p in range(82):
            d={pv[('acc',p)]:1}
            if p<81: lin_add(d,pv[('Dp',p)],-2*P['inf'])
            L.add(('acc',p),d,0)
        for p in range(81):
            deg=len(NB[p]); d={}
            for q in NB[p]: lin_add(d,pv[('own',q)],1); lin_add(d,pv[('opp',q)],-3)
            L.add(('EyeS',p),d,-(deg-2))
    L=prop_layer(L,ex3); layers.append(L)
    def ex4(L,pv):
        for p in range(82):
            d={pv[('acc',p)]:1}
            if p<81: lin_add(d,pv[('EyeS',p)],-P['eye'])
            L.add(('acc',p),d,0)
        for q in range(81):
            d={pv[('opp',q)]:1}
            for n in NB[q]: lin_add(d,pv[('own',n)],1)
            L.add(('U',q),d,-(len(NB[q])-1))
    L=prop_layer(L,ex4); layers.append(L)
    # L5: Weak (from G of L4 incl nbrs), GoodOwn propagated, acc + U
    prev=L; L=Layer(512); pv=prev.names
    for p in range(81): L.add(('own',p),{pv[('own',p)]:1},0)
    for p in range(81): L.add(('opp',p),{pv[('opp',p)]:1},0)
    for p in range(82):
        d={pv[('acc',p)]:1}
        if p<81:
            for q in NB[p]: lin_add(d,pv[('U',q)],P['cap1'])
        L.add(('acc',p),d,0)
    for c in col:
        for s in range(81):
            d={pv[(c,s)]:1, pv[('G',c,s)]:-4}
            for n in NB[s]: lin_add(d,pv[('G',c,n)],-4)
            L.add(('W',c,s),d,0)
    for s in range(81):
        d={pv[('G','own',s)]:1}
        for n in NB[s]: lin_add(d,pv[('G','own',n)],1)
        lin_add(d,pv[('own',s)],5)
        L.add(('G','own',s),d,-5)
    layers.append(L)
    # L6
    prev=L; L=Layer(512); pv=prev.names
    for p in range(82):
        d={pv[('acc',p)]:1}
        if p<81:
            for q in NB[p]: lin_add(d,pv[('W','opp',q)],P['capW'])
        L.add(('acc',p),d,0)
    for p in range(81):
        deg=len(NB[p])
        # SA = relu(2 - e_p - 8*sum GoodOwn(q)) ; e_p = deg - ownN - oppN
        d={}
        for q in NB[p]:
            lin_add(d,pv[('own',q)],1); lin_add(d,pv[('opp',q)],1); lin_add(d,pv[('G','own',q)],-8)
        L.add(('SA',p),d,2-deg)
        d={}
        for q in NB[p]:
            lin_add(d,pv[('W','own',q)],2); lin_add(d,pv[('own',q)],-1); lin_add(d,pv[('opp',q)],-1)
        L.add(('SG',p),d,deg-3)
    layers.append(L)
    out={}
    for k,Lk in enumerate(layers):
        W,b=Lk.mats(); out[f'W{k+1}']=W; out[f'b{k+1}']=b
    W7=np.zeros((512,82),np.float32); b7=np.zeros(82,np.float32)
    nm=L.names
    for p in range(82): W7[nm[('acc',p)],p]=1
    for p in range(81):
        W7[nm[('SA',p)],p]=-P['sa']; W7[nm[('SG',p)],p]=P['save']
    b7[:]=-OFF; b7[81]+=P['pass']
    out['W7']=W7; out['b7']=b7
    return out,layers
P3=dict(OFF=100.0, prior=[0.0,1.0,2.0,2.2,2.4], cap1=4.0, capW=10.0, save=9.0,
       inf=1.0, ownadj=0.0, oppadj=0.3, sa=15.0, eye=20.0, **{'pass':-12.0})
net,layers=build3(P3)
print([len(l.cols) for l in layers])
